"""Shared error type and notification helpers."""


class DepotError(Exception):
    """An operation failed with a machine-readable code. The depot state is left unchanged."""

    def __init__(self, code):
        super().__init__(code)
        self.code = code


def emit(notes, *args):
    """Append one notification (type first, then its arguments) to the ordered log."""
    notes.append(tuple(args))
