"""Money arithmetic. All amounts are integer cents.

Fractional results are converted to whole cents here, using the depot's decimal rounding mode.
"""
import decimal
import os
import tomllib
from decimal import Decimal
from fractions import Fraction

from events import DepotError

DATA_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data.toml")

_MODE_NAMES = (
    "ROUND_CEILING", "ROUND_DOWN", "ROUND_FLOOR", "ROUND_HALF_DOWN",
    "ROUND_HALF_EVEN", "ROUND_HALF_UP", "ROUND_UP", "ROUND_05UP",
)
_MODES = frozenset(getattr(decimal, name) for name in _MODE_NAMES)


def load_data(path=None):
    """Parse the data table (data.toml) and return it as a dict."""
    with open(path or DATA_PATH, "rb") as fh:
        return tomllib.load(fh)


def check_mode(mode):
    if not isinstance(mode, str) or mode not in _MODES:
        raise DepotError("BAD_ARG")


def to_cents(value, mode):
    d = value if isinstance(value, Decimal) else Decimal(str(value))
    return int(d.quantize(Decimal(1), rounding=mode))


def list_price(unit_cost, markup, mode):
    """C08: unit_cost * (1 + markup), rounded to a whole cent."""
    return to_cents(Decimal(unit_cost) * (1 + Decimal(str(markup))), mode)


def sale_revenue(price, qty, bulk_threshold, bulk_discount_pct, mode):
    """C07 + C09: price * qty, less the bulk discount for sales of at least bulk_threshold units."""
    gross = Decimal(price * qty)
    if qty >= bulk_threshold:
        gross = gross * (100 - Decimal(str(bulk_discount_pct))) / 100
    return to_cents(gross, mode)


def storage_charge(units, cents_per_unit_day):
    """C19: storage charge for one day."""
    return units * cents_per_unit_day


def transfer_cost(qty, cents_per_unit):
    """C11: cost charged to the sending side."""
    return qty * cents_per_unit


def late_payment(unit_cost, qty, penalty_pct, mode):
    """C18: amount paid for a late delivery, reduced by penalty_pct percent.

    penalty_pct is not yet decided by the owner. If it is None this raises PENALTY_UNSET.
    """
    if penalty_pct is None:
        raise DepotError("PENALTY_UNSET")
    total = Decimal(unit_cost * qty)
    return to_cents(total * (100 - Decimal(str(penalty_pct))) / 100, mode)


def turnover(ship_log, held_log, start, end):
    """C30: units shipped in [start, end] divided by the average units held over those days.

    held_log[d] is the number of units held at the start of day d.
    Returns None when the average held is zero.
    """
    shipped = sum(q for d, q in ship_log if start <= d <= end)
    days = end - start + 1
    avg = Fraction(sum(held_log[start:end + 1]), days)
    if avg == 0:
        return None
    return float(Fraction(shipped) / avg)
