"""Seeded demand simulation (C29)."""
import random

from events import DepotError
from money import load_data


def simulate(days, seed):
    """Return one list of (sku, qty) customer orders per day.

    Each sku in the demand table gets a qty drawn uniformly from its [min, max] range each day.
    Zero-quantity draws produce no order. Only a random.Random(seed) generator is used.
    """
    if type(days) is not int or days < 0:
        raise DepotError("BAD_ARG")
    demand = load_data()["demand"]
    skus = sorted(demand)
    rng = random.Random(seed)
    result = []
    for _ in range(days):
        orders = []
        for sku in skus:
            qty = rng.randint(demand[sku]["min"], demand[sku]["max"])
            if qty > 0:
                orders.append((sku, qty))
        result.append(orders)
    return result
